.wst-pagebreak {
	clear:both;
	display:block;
	break-after:page;
	page-break-after:always;
	text-align:center;
}
.wst-pagebreak > span > span {
	clear:both;
	display:block;
	font-size:83%;
	border-color:#999999;
}
.wst-pagebreak-top > span > span {
	border-top-width:1px;
	border-top-style:dashed;
}
.wst-pagebreak-bottom > span > span {
	border-bottom-width:1px;
	border-bottom-style:dashed;
}

.wst-asc {
	font-variant: all-small-caps;	
}

.wst-asc-initials {
	white-space: nowrap;	
}

.wst-asc-initials > span:not(:first-child) {
	padding-left: 0.16em; /* about 1/6em ~= &thinsp; */
}

.wst-asc-initials.wst-asc-initials-nospace  > span:not(:first-child){
	padding-left:0;
}

.wst-asterisks {
	display: block;
	margin: auto;
	text-align: center;
}

.wst-bar {
	text-decoration: line-through;
}

.wst-bar-inner {
	color: transparent;
}

.wst-custom-rule {
	text-align:center;
	margin:1em auto 1em auto;
	background-color:transparent;
	color:inherit;
}
.wst-custom-rule.wst-custom-rule-inline {
	display:block;
	border-collapse:collapse;
	border-spacing:0 0;
	margin:0 auto 0 auto;
}

.skin-theme-clientpref-night .wst-custom-rule {
	filter:invert(1) hue-rotate(180deg);
}
@media(prefers-color-scheme: dark) {
	.skin-theme-clientpref-os .wst-custom-rule {
		filter:invert(1) hue-rotate(180deg);
	}
}

