/* Base style */

.wst-rh {
	display:flex;
	width:100%;
	text-align:center;
	justify-content:space-between;
}
.wst-rh > div {
	flex:auto;
}
.wst-rh > div:first-child {
	text-align:left;
}
.wst-rh > div:last-child {
	text-align:right;
}
.wst-rh > div > p {
	margin:0;
}

/* 1 cell */

.wst-rh.wst-rh-1 {
	justify-content:center;
}
.wst-rh.wst-rh-1 > div:first-child {
	text-align:center;
}

.wst-block-center {
	display:block;
	margin:0 auto;
	padding:0;
	position:relative;
	/* width:fit-content; */
	max-width:100%;
	height:auto;
	text-align:initial;
}
.wst-block-center-title {
	display:inline-block;
	width:100%;
	text-align:center;
}

/*
 * Styles for the block right template
 */

.wst-block-right {
	float:right;
	max-width:100%;
	text-align:inherit;
	margin-left:0;
	margin-right:0;
}

/* When collapsing paragraphs, remove the site-default inter-para spacing */
.wst-block-right-collapse p {
	margin-top:0;
	margin-bottom:0;
}

/* Undo the site-default 0.5em of the preceding paragraph, so
 * the block right content doesn't have a gap */
.wst-block-right-collapse {
	margin-top: -0.5em;
}

.pmbox {
	margin: 4px 0;
	border-collapse: collapse;
	border: 1px solid #a2a9b1;    /* Default "notice" gray */
	background-color: #f8f9fa;
	box-sizing: border-box;
}

/* For the "small=yes" option. */
.pmbox.mbox-small {
	font-size: 88%;
	line-height: 1.25em;
}

.pmbox-speedy {
	border: 2px solid #b32424;    /* Red */
	background-color: #fee7e6;    /* Pink */
}

.pmbox-delete {
	border: 2px solid #b32424;    /* Red */
}

.pmbox-content {
	border: 1px solid #f28500;    /* Orange */
}

.pmbox-style {
	border: 1px solid #fc3;       /* Yellow */
}

.pmbox-move {
	border: 1px solid #9932cc;    /* Purple */
}

.pmbox-protection {
	border: 2px solid #a2a9b1;    /* Gray-gold */
}

.pmbox .mbox-text {
	border: none;
	/* @noflip */
	padding: 0.25em 0.9em;
	width: 100%;
}

.pmbox .mbox-image {
	border: none;
	/* @noflip */
	padding: 2px 0 2px 0.9em;
	text-align: center;
}

.pmbox .mbox-imageright {
	border: none;
	/* @noflip */
	padding: 2px 0.9em 2px 0;
	text-align: center;
}

/* Workaround for max-width:100% in [[MediaWiki:Gadget-PageNumbers.js]] */
.pmbox .mbox-image img, .pmbox .mbox-imageright img {
	max-width: none;
}

/* An empty narrow cell */
.pmbox .mbox-empty-cell {
	border: none;
	padding: 0;
	width: 1px;
}

.pmbox .mbox-invalid-type {
	text-align: center;
}

@media (min-width: 720px) {
	.pmbox {
		margin: 4px 10%;
	}

	.pmbox.mbox-small {
		/* @noflip */
		clear: right;
		/* @noflip */
		float: right;
		/* @noflip */
		margin: 4px 0 4px 1em;
		width: 238px;
	}
}

.wst-right {
	text-align:right;
}

.wst-right {
	text-align:right;
}

.wst-right {
	text-align:right;
}

/*
 * This applies to all _Ancient_ Greek via the "Greek" template.
 * Until [[T289777]] is done, there is no obvious way
 * (there is a very non-obvious way) to set a webfont for a lang code,
 * so apply something that we hope will get a decent result on most user agents.
 */
.wst-lang-grc {
	font-family: GentiumPlus;
	font-feature-settings: 'cv78' on, 'cv83' on;
}

.wst-block-left {
	float: left;
	width: auto;
	text-align: inherit;
	margin-left: 0;
	padding-right: 0;
}
.wst-block-left-clear-top {
	clear: left;
}

.dropinitial {
	float: left;
	text-indent: 0;
}

.dropinitial .dropinitial-fl {
	float: left;
	position: relative;
	vertical-align: top;
	line-height: 1;
}

.dropinitial .dropinitial-mid .dropinitial-initial {
	/* also float this inner span so the margins still work */
	float: left;

	line-height:1em;

	/* reset any text-indent because otherwise it will also appear
     * in between the 'fl' text and the initial itself */
	text-indent: 0;

	font-size:3em;

	margin:0 0.1em 0 0;
}

.dropinitial-firstword {
	text-transform: uppercase;
}

/* Further formatting unique to dropinitials inside ppoem is found at [[Template:Ppoem/styles.css]] */

.skin-theme-clientpref-night .wst-drop-initial-night-mode-invert {
	filter:invert(1) hue-rotate(180deg);
}
@media(prefers-color-scheme: dark) {
	.skin-theme-clientpref-os .wst-drop-initial-night-mode-invert {
		filter:invert(1) hue-rotate(180deg);
	}
}

