.wst-main-heading, .wst-subheading {
	text-align:center;
	margin:0.5em auto;
}
.wst-main-heading {
	font-size:120%;
}

.wst-heading-leveled {
	text-align:center;
	margin-top:0.3em;
}
.wst-heading-leveled.wst-heading-leveled-1 {
	font-size:180%;
	margin-top:1em;
}
.wst-heading-leveled.wst-heading-leveled-2 {
	font-size:150%;
	margin-top:1em;
}
.wst-heading-leveled.wst-heading-leveled-3 {
	font-size:120%;
}

